index a537d993..429a346a 100644
--- a/.github/workflows/ci.yml
+++ b/.github/workflows/ci.yml
@@ -49,12 +49,15 @@ on:
         type: string
         default: "0"

-# T-178: a push and the pull request for that branch share one group, and the
-# newer run cancels the older. A dispatch uses its own group. A push to master
+# T-178: a newer run cancels the older one in its group. T-221 (D-094 a): the group
+# holds the EVENT, so a branch's push run and its pull request run never cancel each
+# other (a cancelled check on the head SHA reads as failing to ruleset 24343321);
+# a newer push still cancels the older push, a newer PR commit the older PR run.
+# A dispatch uses its own group. A push to master
 # does not cancel: two merges close together must both get a result. The second
 # master push waits in the ci-master group; it is not cancelled.
 concurrency:
-  group: "${{ github.event_name == 'workflow_dispatch' && format('ci-dispatch-{0}', github.run_id) || format('ci-{0}', github.head_ref || github.ref_name) }}"
+  group: "${{ github.event_name == 'workflow_dispatch' && format('ci-dispatch-{0}', github.run_id) || format('ci-{0}-{1}', github.event_name, github.head_ref || github.ref_name) }}"
   cancel-in-progress: "${{ github.event_name != 'workflow_dispatch' && github.ref != 'refs/heads/master' }}"

